/* ---- film 096 helpers ---- */
/* the golden Cantor gate image: 512 depth-9 prefixes, plotted by their SU(2) coordinates (a_x, a_y, a_z) */
/* prefix centres: CEN96[d][m] = mean gate coordinates of the prefixes whose first d bits are m */
const CEN96 = (() => { const out = []; for (let d = 0; d <= 9; d++) { const n = 1 << d, acc = []; for (let m = 0; m < n; m++) acc.push([0, 0, 0, 0]); CAN96.forEach((p, i) => { const m = i & (n - 1); acc[m][0] += p[0]; acc[m][1] += p[1]; acc[m][2] += p[2]; acc[m][3] += 1; }); out.push(acc.map(c => [c[0] / c[3], c[1] / c[3], c[2] / c[3]])); } return out; })();
/* flat view: x = a_x (odd layers, X axis), y = a_z (even layers, Z axis), each axis normalised to its range */
function cantor96(cx, cy, w, h, a, o = {}) {
  if (a <= 0) return;
  const prog = o.prog == null ? 1 : o.prog, f = prog * 10;
  const M = p => [cx + p[0] / 0.66 * w, cy - p[1] / 0.245 * h];
  const P = CEN96.map(level => level.map(M));
  for (let d = 1; d <= 9; d++) {
    const q = clamp(f - d + 1); if (q <= 0) break;
    P[d].forEach((c, m) => { const par = P[d - 1][m & ((1 << (d - 1)) - 1)]; line(par[0], par[1], c[0], c[1], ((m >> (d - 1)) & 1) ? C.gold : C.cyan, a * q * 0.32, Math.max(0.8, 2.6 * Math.pow(0.8, d))); });
  }
  for (let d = 0; d <= 9; d++) {
    const qa = d < 9 ? clamp(f - d) - clamp(f - d - 1) * 0.85 : clamp(f - d); if (qa <= 0.01) continue;
    const r = Math.max(o.r || 3.6, 24 * Math.pow(0.66, d));
    P[d].forEach((c, m) => dot(c[0], c[1], r, (m & 1) ? 'g' : 'c', a * qa));
  }
}
function bar96(x, y0, w, h, col, a, lab, val, size = 16) {
  if (a <= 0) return;
  fillBox(x, y0 - h, w, h, col, a * 0.45); rect63(x, y0 - h, w, h, col, a, 1.6);
  if (val != null) lbl(val, x + w / 2, y0 - h - 10, C.white, a, size);
  if (lab != null) lbl(lab, x + w / 2, y0 + 24, C.dim, a, 15);
}
function cell73(x, y, w, h, s, col, a, size = 20, fillA = 0.35) { if (a <= 0) return; fillBox(x, y, w, h, col, a * fillA); rect63(x, y, w, h, col, a, 1.6); lbl(s, x + w / 2, y + h / 2 + size * 0.35, C.white, a, size); }
function node96(x, y, r, s, col, a, size = 20) { if (a <= 0) return; fillEll73(x, y, r, r, col, a * 0.18); ring(x, y, r, col, a, 2.5); lbl(s, x, y + size * 0.36, C.white, a, size); }
function ell73(cx, cy, rx, ry, col, a, lw = 1.5, rot = 0, dash = 0) {
  if (a <= 0) return;
  ctx.save(); ctx.globalAlpha = a; ctx.strokeStyle = col; ctx.lineWidth = lw; if (dash) ctx.setLineDash([8, 7]); ctx.beginPath();
  ctx.ellipse(cx, cy, Math.max(rx, 0.1), Math.max(ry, 0.1), rot, 0, Math.PI * 2); ctx.stroke(); ctx.restore();
}
function fillEll73(cx, cy, rx, ry, col, a) {
  if (a <= 0) return;
  ctx.save(); ctx.globalAlpha = a; ctx.fillStyle = col; ctx.beginPath(); ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2); ctx.fill(); ctx.restore();
}
const X96 = (Math.sqrt(5) - 1) / 2;

